fn perf_sample_data_init(data: &mut perf_sample_data, addr: u64, period: u64) {
// remaining struct members initialized in perf_prepare_sample()
unsafe {
(*(data as *mut perf_sample_data)).sample_flags = 256;
}
unsafe {
(*(data as *mut perf_sample_data)).period = period;
}
unsafe {
(*(data as *mut perf_sample_data)).dyn_size = 0;
}
if addr != 0 {
unsafe {
(*(data as *mut perf_sample_data)).addr = addr;
}
unsafe {
(*data).sample_flags = (*data).sample_flags | 8;
}
}
}

